#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;vector<pair<string,int>>st;
string cur;int num=0;
for(char c:s){
if(isdigit((unsigned char)c))num=num*10+(c-'0');
else if(c=='['){st.push_back({cur,num});cur="";num=0;}
else if(c==']'){auto pr=st.back();st.pop_back();
string t2;for(int i=0;i<pr.second;++i)t2+=cur;cur=pr.first+t2;}
else cur+=c;}
printf("%s\n",cur.c_str());return 0;}

